UPDATE MSVMMBRDEF SET USE_RANGE_FLAG = ' ' WHERE USE_RANGE_FLAG <> 'Y' AND USE_RANGE_FLAG <> ' ';
UPDATE MSVMSVCMBR SET REQ_MEMBER_FLAG = 'O' WHERE REQ_MEMBER_FLAG <> 'M' AND REQ_MEMBER_FLAG <> 'O';
UPDATE MSVMSVCMBR SET OVERRIDE_FLAG = ' ' WHERE OVERRIDE_FLAG <> 'Y' AND OVERRIDE_FLAG <> ' ';
UPDATE MSVMSVCMBR SET USE_RANGE_FLAG = ' ' WHERE USE_RANGE_FLAG <> 'Y' AND USE_RANGE_FLAG <> ' ';

CREATE TABLE MSVMSVCMBR_OLD AS
SELECT * FROM MSVMSVCMBR;

DROP TABLE MSVMSVCMBR CASCADE CONSTRAINT PURGE;

/* MSVMMBRDEF : Service Management Service Member Table */
CREATE TABLE MSVMSVCMBR
(
  MODULE_NAME                  VARCHAR2(30)      DEFAULT (' ')    NOT NULL,
  SERVICE_NAME                 VARCHAR2(100)     DEFAULT (' ')    NOT NULL,
  DIRECTION                    CHAR(1)           DEFAULT (' ')    NOT NULL,
  MEMBER_PATH           	   VARCHAR2(1000)    DEFAULT (' ')    NOT NULL,
  MEMBER_DEPTH                 NUMBER(6)         DEFAULT (0)      NOT NULL,
  MEMBER_SEQ                   NUMBER(6)         DEFAULT (0)      NOT NULL,
  PARENT_MEMBER_PATH           VARCHAR2(1000)    DEFAULT (' ')    NOT NULL,
  MEMBER_NAME                  VARCHAR2(50)      DEFAULT (' ')    NOT NULL,
  MEMBER_DESC_1                VARCHAR2(1000)    DEFAULT (' ')    NOT NULL,
  MEMBER_DESC_2                VARCHAR2(1000)    DEFAULT (' ')    NOT NULL,
  MEMBER_DESC_3                VARCHAR2(1000)    DEFAULT (' ')    NOT NULL,
  MEMBER_TYPE                  VARCHAR2(10)      DEFAULT (' ')    NOT NULL,
  MEMBER_SIZE                  NUMBER(6)         DEFAULT (0)      NOT NULL,
  MEMBER_PRT                   VARCHAR2(50)      DEFAULT (' ')    NOT NULL,
  ARRAY_TYPE                   VARCHAR2(10)      DEFAULT (' ')    NOT NULL,
  REQ_MEMBER_FLAG              CHAR(1)           DEFAULT (' ')    NOT NULL,
  OVERRIDE_FLAG                CHAR(1)           DEFAULT (' ')    NOT NULL,
  USE_RANGE_FLAG               CHAR(1)           DEFAULT (' ')    NOT NULL,
  RANGE_MIN                    NUMBER(22,4)      DEFAULT (0)      NOT NULL,
  RANGE_MAX                    NUMBER(22,4)      DEFAULT (0)      NOT NULL,
    /* Create/Update Info. */
    CREATE_USER_ID              VARCHAR2(20)     DEFAULT(' ')    NOT NULL,
    CREATE_TIME                 VARCHAR2(14)     DEFAULT(' ')    NOT NULL,
    UPDATE_USER_ID              VARCHAR2(20)     DEFAULT(' ')    NOT NULL,
    UPDATE_TIME                 VARCHAR2(14)     DEFAULT(' ')    NOT NULL
) TABLESPACE MESPLUS_DATA_TS;

ALTER TABLE MSVMSVCMBR 
ADD CONSTRAINT MSVMSVCMBR_PK PRIMARY KEY
(
  MODULE_NAME, 
  SERVICE_NAME, 
  DIRECTION, 
  MEMBER_PATH
) USING INDEX TABLESPACE MESPLUS_IDX_TS;

DECLARE
	   V_PATH	VARCHAR2(1000);
BEGIN
	 FOR REC IN (
			SELECT * 
			FROM MSVMSVCMBR_OLD
			ORDER BY MODULE_NAME, SERVICE_NAME, DIRECTION, MEMBER_DEPTH, MEMBER_SEQ
	 )
	 LOOP
		  IF REC.PARENT_MEMBER_NAME = ' ' THEN
				REC.MODULE_NAME        ,
				REC.SERVICE_NAME       ,
				REC.DIRECTION          ,
				REC.MEMBER_NAME        ,
				REC.MEMBER_DEPTH       ,
				REC.MEMBER_SEQ         ,
				' '                    ,
				REC.MEMBER_NAME        ,
				REC.MEMBER_DESC_1      ,
				REC.MEMBER_DESC_2      ,
				REC.MEMBER_DESC_3      ,
				REC.MEMBER_TYPE        ,
				REC.MEMBER_SIZE        ,
				REC.MEMBER_PRT         ,
				REC.ARRAY_TYPE         ,
				REC.REQ_MEMBER_FLAG    ,
				REC.OVERRIDE_FLAG      ,
				REC.USE_RANGE_FLAG     ,
				REC.RANGE_MIN          ,
				REC.RANGE_MAX          ,
				REC.CREATE_USER_ID     ,
				REC.CREATE_TIME        ,
				REC.UPDATE_USER_ID     ,
				REC.UPDATE_TIME
			 );
		  ELSE
		  	  BEGIN
			  	  SELECT MEMBER_PATH
				  INTO  V_PATH
				  FROM MSVMSVCMBR 
				  WHERE MODULE_NAME = REC.MODULE_NAME
				  		AND SERVICE_NAME = REC.SERVICE_NAME
						AND DIRECTION = REC.DIRECTION
						AND MEMBER_NAME = REC.PARENT_MEMBER_NAME
						AND MEMBER_DEPTH = REC.MEMBER_DEPTH - 1;
					REC.MODULE_NAME        ,
					REC.SERVICE_NAME       ,
					REC.DIRECTION          ,
					V_PATH||'/'||REC.MEMBER_NAME ,
					REC.MEMBER_DEPTH       ,
					REC.MEMBER_SEQ         ,
					V_PATH                 ,
					REC.MEMBER_NAME        ,
					REC.MEMBER_DESC_1      ,
					REC.MEMBER_DESC_2      ,
					REC.MEMBER_DESC_3      ,
					REC.MEMBER_TYPE        ,
					REC.MEMBER_SIZE        ,
					REC.MEMBER_PRT         ,
					REC.ARRAY_TYPE         ,
					REC.REQ_MEMBER_FLAG    ,
					REC.OVERRIDE_FLAG      ,
					REC.USE_RANGE_FLAG     ,
					REC.RANGE_MIN          ,
					REC.RANGE_MAX          ,
					REC.CREATE_USER_ID     ,
					REC.CREATE_TIME        ,
					REC.UPDATE_USER_ID     ,
					REC.UPDATE_TIME
				 );
		  		 EXCEPTION WHEN OTHERS  THEN 
						REC.MODULE_NAME        ,
						REC.SERVICE_NAME       ,
						REC.DIRECTION          ,
						'zzz'||TO_CHAR(CURRENT_TIMESTAMP) ,
						REC.MEMBER_DEPTH       ,
						REC.MEMBER_SEQ         ,
						REC.PARENT_MEMBER_NAME ,
						REC.MEMBER_NAME        ,
						REC.MEMBER_DESC_1      ,
						REC.MEMBER_DESC_2      ,
						REC.MEMBER_DESC_3      ,
						REC.MEMBER_TYPE        ,
						REC.MEMBER_SIZE        ,
						REC.MEMBER_PRT         ,
						REC.ARRAY_TYPE         ,
						REC.REQ_MEMBER_FLAG    ,
						REC.OVERRIDE_FLAG      ,
						REC.USE_RANGE_FLAG     ,
						REC.RANGE_MIN          ,
						REC.RANGE_MAX          ,
						REC.CREATE_USER_ID     ,
						REC.CREATE_TIME        ,
						REC.UPDATE_USER_ID     ,
						REC.UPDATE_TIME
					 );
			  END;
		  END IF;
	  END LOOP;			
END ;
/

