CREATE TABLE MWIPBATDEF_OLD AS
SELECT * FROM MWIPBATDEF;

DROP TABLE MWIPBATDEF CASCADE CONSTRAINTS PURGE;

CREATE TABLE MWIPBATDEF
(
  FACTORY         VARCHAR2(10 BYTE)             DEFAULT (' ')                 NOT NULL,
  BATCH_ID        VARCHAR2(30 BYTE)             DEFAULT (' ')                 NOT NULL,
  ITEM_ID         VARCHAR2(30 BYTE)             DEFAULT (' ')                 NOT NULL,
  SEQ_NUM         NUMBER(6)                     DEFAULT (0)                   NOT NULL,
  ITEM_TYPE       CHAR(1 BYTE)                  DEFAULT (' ')                 NOT NULL,
  OPER         VARCHAR2(10 BYTE)             DEFAULT (' ')                 NOT NULL,
  REL_LEVEL       CHAR(1 BYTE)                  DEFAULT (' ')                 NOT NULL,
  RES_ID         VARCHAR2(20 BYTE)             DEFAULT (' ')                 NOT NULL,
  RESG_ID         VARCHAR2(20 BYTE)             DEFAULT (' ')                 NOT NULL,
  RES_TYPE         VARCHAR2(20 BYTE)             DEFAULT (' ')                 NOT NULL,
  CRT_RULE_ID         VARCHAR2(30 BYTE)             DEFAULT (' ')                 NOT NULL,
  GEN_RULE_ID         VARCHAR2(30 BYTE)             DEFAULT (' ')                 NOT NULL,
  CREATE_USER_ID  VARCHAR2(20 BYTE)             DEFAULT (' ')                 NOT NULL,
  CREATE_TIME     VARCHAR2(14 BYTE)             DEFAULT (' ')                 NOT NULL,
  UPDATE_USER_ID  VARCHAR2(20 BYTE)             DEFAULT (' ')                 NOT NULL,
  UPDATE_TIME     VARCHAR2(14 BYTE)             DEFAULT (' ')                 NOT NULL,
  CONFIRM_FLAG    CHAR(1 BYTE)                  DEFAULT (' ')                 NOT NULL,
  BATCH_COMMENT   VARCHAR2(200 BYTE)            DEFAULT (' ')                 NOT NULL
) TABLESPACE MESPLUS_DATA_TS;

COMMENT ON TABLE MWIPBATDEF IS 'Batch Definition Table';

ALTER TABLE MWIPBATDEF 
ADD CONSTRAINT MWIPBATDEF_PK PRIMARY KEY
(
    FACTORY, 
    BATCH_ID, 
    ITEM_ID, 
    SEQ_NUM
) USING INDEX TABLESPACE MESPLUS_IDX_TS;

CREATE UNIQUE INDEX MWIPBATDEF_IDX_1 ON MWIPBATDEF
(FACTORY, BATCH_ID, SEQ_NUM)
TABLESPACE MESPLUS_IDX_TS;


CREATE INDEX MWIPBATDEF_IDX_2 ON MWIPBATDEF
(FACTORY, ITEM_TYPE, ITEM_ID)
TABLESPACE MESPLUS_IDX_TS;


          BATCH_ID       ,
          ITEM_ID        ,
          SEQ_NUM        ,
          ITEM_TYPE      ,
          ' ',
          ' ',
          ' ',
          ' ',
          ' ',
          ' ',
          ' ',
          CREATE_USER_ID ,
          CREATE_TIME    ,
          UPDATE_USER_ID ,
          UPDATE_TIME    ,
          ' '   ,
          ' '  
FROM MWIPBATDEF_OLD);

CREATE TABLE MWIPBATHIS_OLD AS
SELECT * FROM MWIPBATHIS;

DROP TABLE MWIPBATHIS CASCADE CONSTRAINTS PURGE;

CREATE TABLE MWIPBATHIS
(
  FACTORY         VARCHAR2(10 BYTE)             DEFAULT (' ')                 NOT NULL,
  BATCH_ID        VARCHAR2(30 BYTE)             DEFAULT (' ')                 NOT NULL,
  TRAN_TIME       VARCHAR2(14 BYTE)             DEFAULT (' ')                 NOT NULL,
  TRAN_CODE       VARCHAR2(12 BYTE)             DEFAULT (' ')                 NOT NULL,
  ITEM_ID         VARCHAR2(30 BYTE)             DEFAULT (' ')                 NOT NULL,
  SEQ_NUM         NUMBER(6)                     DEFAULT (0)                   NOT NULL,
  ITEM_HIST_SEQ   NUMBER(10)                    DEFAULT (0)                   NOT NULL,
  ITEM_TYPE       CHAR(1 BYTE)                  DEFAULT (' ')                 NOT NULL,
  OPER         VARCHAR2(10 BYTE)             DEFAULT (' ')                 NOT NULL,
  REL_LEVEL       CHAR(1 BYTE)                  DEFAULT (' ')                 NOT NULL,
  RES_ID         VARCHAR2(20 BYTE)             DEFAULT (' ')                 NOT NULL,
  RESG_ID         VARCHAR2(20 BYTE)             DEFAULT (' ')                 NOT NULL,
  RES_TYPE         VARCHAR2(20 BYTE)             DEFAULT (' ')                 NOT NULL,
  CRT_RULE_ID         VARCHAR2(30 BYTE)             DEFAULT (' ')                 NOT NULL,
  GEN_RULE_ID         VARCHAR2(30 BYTE)             DEFAULT (' ')                 NOT NULL,
  CREATE_USER_ID  VARCHAR2(20 BYTE)             DEFAULT (' ')                 NOT NULL,
  CONFIRM_FLAG    CHAR(1 BYTE)                  DEFAULT (' ')                 NOT NULL,
  BATCH_COMMENT   VARCHAR2(200 BYTE)            DEFAULT (' ')                 NOT NULL
) TABLESPACE MESPLUS_DATA_TS;

COMMENT ON TABLE MWIPBATHIS IS 'Batch History Table';

ALTER TABLE MWIPBATHIS 
ADD CONSTRAINT MWIPBATHIS_PK PRIMARY KEY
(
    FACTORY, 
    BATCH_ID, 
    TRAN_TIME, 
    TRAN_CODE, 
    SEQ_NUM
) USING INDEX TABLESPACE MESPLUS_IDX_TS;



